    static func kit(_ colour: Side.Colour) -> Kit {
        switch colour {
        case .lime: Kit(fill: RGBA(0xC6FF3D), ink: RGBA(0x0B0F14), outline: nil)
        case .coral: Kit(fill: RGBA(0xFF6B4A), ink: RGBA(0x0B0F14), outline: nil)
