        case .yellow: Kit(fill: RGBA(0xFFD84A), ink: RGBA(0x0B0F14), outline: nil)
        case .green: Kit(fill: RGBA(0x2BD67B), ink: RGBA(0x0B0F14), outline: nil)
        case .purple: Kit(fill: RGBA(0xB79CFF), ink: RGBA(0x0B0F14), outline: nil)
        case .black: Kit(fill: RGBA(0x15181C), ink: RGBA(0xFFFFFF), outline: RGBA(0xE6E9EC))
        case .white: Kit(fill: RGBA(0xF2F5F7), ink: RGBA(0x0B0F14), outline: nil)
        case .sky: Kit(fill: RGBA(0x5BC8FF), ink: RGBA(0x0B0F14), outline: nil)
